+++ 
@@ -0,0 +1,994 @@
+<!DOCTYPE html>
+<html lang="ru">
+
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
+    <title>Доработка схемы · ЭликсToFix</title>
+    <link rel="icon" type="image/png" href="ava.png">
+    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css">
+    <style>
+        :root {
+            --primary-color: #1a2b3c;
+            --secondary-color: #2c3e50;
+            --accent-color: #3498db;
+            --accent-light: #5dade2;
+            --xgt-color: #e74c3c;
+            --lxt-color: #3498db;
+            --success-color: #27ae60;
+            --warning-color: #ff9800;
+            --text-color: #333;
+            --transition-speed: 0.3s;
+            --radius-sm: 10px;
+            --radius-md: 14px;
+            --radius-lg: 20px;
+            --shadow-sm: 0 2px 10px rgba(0, 0, 0, 0.06);
+            --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.1);
+            --shadow-lg: 0 16px 40px rgba(0, 0, 0, 0.16);
+        }
+
+        * {
+            box-sizing: border-box;
+            margin: 0;
+            padding: 0;
+        }
+
+        html {
+            scroll-behavior: smooth;
+        }
+
+        body {
+            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+            background: radial-gradient(90rem 90rem at 110% -10%, rgba(162, 28, 175, 0.18), transparent 60%),
+                radial-gradient(80rem 80rem at -10% 15%, rgba(8, 145, 178, 0.22), transparent 55%),
+                #f3f4f6;
+            color: var(--text-color);
+            line-height: 1.6;
+            min-height: 100vh;
+        }
+
+        /* Аккуратный скроллбар */
+        ::-webkit-scrollbar {
+            width: 10px;
+        }
+
+        ::-webkit-scrollbar-track {
+            background: #e9ecf1;
+        }
+
+        ::-webkit-scrollbar-thumb {
+            background: #b6c2cf;
+            border-radius: 6px;
+        }
+
+        ::-webkit-scrollbar-thumb:hover {
+            background: var(--accent-color);
+        }
+
+        .container {
+            max-width: 1200px;
+            margin: 0 auto;
+            padding: 20px;
+        }
+
+        header {
+            text-align: center;
+            padding: 22px 0;
+            background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 45%, #14213d 100%);
+            color: white;
+            border-radius: var(--radius-lg);
+            margin-bottom: 24px;
+            box-shadow: var(--shadow-lg);
+            border: 1px solid rgba(255, 255, 255, 0.12);
+            position: relative;
+            overflow: hidden;
+        }
+
+        header::before {
+            content: "";
+            position: absolute;
+            top: 0;
+            left: 0;
+            right: 0;
+            height: 4px;
+            background: linear-gradient(90deg, var(--accent-color), #8e44ad, var(--xgt-color), var(--accent-color));
+            background-size: 300% 100%;
+            animation: header-shimmer 6s linear infinite;
+        }
+
+        @keyframes header-shimmer {
+            0% {
+                background-position: 0% 0;
+            }
+
+            100% {
+                background-position: 100% 0;
+            }
+        }
+
+        header h1 {
+            font-size: 2rem;
+            margin-bottom: 8px;
+            color: #fff;
+            font-weight: 800;
+            letter-spacing: 0.5px;
+            text-shadow: 2px 2px 6px rgba(0, 0, 0, 0.55);
+            line-height: 1.3;
+            padding: 0 20px;
+        }
+
+        header h1 i {
+            color: var(--accent-light);
+            margin-right: 8px;
+            text-shadow: 0 0 14px rgba(93, 173, 226, 0.8);
+        }
+
+        header p {
+            font-size: 1.05rem;
+            opacity: 0.95;
+            max-width: 800px;
+            margin: 0 auto 8px;
+            color: white;
+            text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.3);
+            line-height: 1.6;
+        }
+
+/* ===== Выдвижное меню (бургер) ===== */
+        .hamburger {
+            position: sticky;
+            top: 12px;
+            z-index: 30;
+            display: flex;
+            flex-direction: column;
+            justify-content: center;
+            align-items: center;
+            gap: 5px;
+            width: 54px;
+            height: 54px;
+            margin-right: auto;
+            margin-bottom: 18px;
+            background: linear-gradient(135deg, #f59e0b 0%, #ef4444 55%, #dc2626 100%);
+            border: 2px solid rgba(255, 255, 255, 0.85);
+            border-radius: 14px;
+            box-shadow: 0 8px 24px rgba(239, 68, 68, 0.45), 0 4px 10px rgba(0, 0, 0, 0.2);
+            cursor: pointer;
+            transition: transform 0.3s ease, box-shadow 0.3s ease;
+            animation: hamburger-pulse 2.4s ease-in-out infinite;
+        }
+
+        @keyframes hamburger-pulse {
+            0%,
+            100% {
+                box-shadow: 0 8px 24px rgba(239, 68, 68, 0.45), 0 4px 10px rgba(0, 0, 0, 0.2);
+            }
+
+            50% {
+                box-shadow: 0 10px 32px rgba(239, 68, 68, 0.7), 0 4px 12px rgba(0, 0, 0, 0.25);
+            }
+        }
+
+        .hamburger:hover {
+            transform: translateY(-2px) scale(1.06);
+            box-shadow: 0 12px 34px rgba(239, 68, 68, 0.6), 0 4px 12px rgba(0, 0, 0, 0.25);
+        }
+
+        .hamburger span {
+            display: block;
+            width: 26px;
+            height: 3.5px;
+            background: #fff;
+            border-radius: 3px;
+            transform-origin: center;
+            transition: all 0.3s ease;
+        }
+
+        .hamburger.active {
+            animation: none;
+        }
+
+        .hamburger.active span:nth-child(1) {
+            transform: translateY(8.5px) rotate(45deg);
+        }
+
+        .hamburger.active span:nth-child(2) {
+            opacity: 0;
+        }
+
+        .hamburger.active span:nth-child(3) {
+            transform: translateY(-8.5px) rotate(-45deg);
+        }
+
+        /* Затемнение фона */
+        .side-overlay {
+            position: fixed;
+            inset: 0;
+            background: rgba(0, 0, 0, 0.5);
+            opacity: 0;
+            visibility: hidden;
+            transition: opacity 0.3s ease, visibility 0.3s ease;
+            z-index: 40;
+        }
+
+        .side-overlay.open {
+            opacity: 1;
+            visibility: visible;
+        }
+
+        /* Выдвижная панель */
+        .side-menu {
+            position: fixed;
+            top: 0;
+            left: 0;
+            height: 100vh;
+            width: 300px;
+            max-width: 85vw;
+            background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 65%, #14213d 100%);
+            padding: 22px 18px;
+            transform: translateX(-105%);
+            transition: transform 0.35s ease;
+            z-index: 50;
+            overflow-y: auto;
+            box-shadow: var(--shadow-lg);
+        }
+
+        .side-menu.open {
+            transform: translateX(0);
+        }
+
+        .side-menu-header {
+            display: flex;
+            align-items: center;
+            justify-content: space-between;
+            color: #fff;
+            font-size: 1.1rem;
+            font-weight: 700;
+            padding-bottom: 16px;
+            margin-bottom: 16px;
+            border-bottom: 1px solid rgba(255, 255, 255, 0.14);
+        }
+
+        .side-menu-header i {
+            color: var(--accent-light);
+            margin-right: 8px;
+        }
+
+        .side-menu-close {
+            background: rgba(255, 255, 255, 0.1);
+            border: 1px solid rgba(255, 255, 255, 0.2);
+            color: #fff;
+            width: 34px;
+            height: 34px;
+            border-radius: 8px;
+            display: flex;
+            align-items: center;
+            justify-content: center;
+            cursor: pointer;
+            font-size: 1rem;
+            transition: all 0.3s ease;
+        }
+
+        .side-menu-close:hover {
+            background: var(--xgt-color);
+        }
+
+        .side-menu-links {
+            display: flex;
+            flex-direction: column;
+            gap: 10px;
+        }
+
+        .side-menu .nav-link {
+            display: flex;
+            align-items: center;
+            gap: 12px;
+            color: #e8eef5;
+            text-decoration: none;
+            padding: 13px 16px;
+            border: 1px solid rgba(255, 255, 255, 0.16);
+            border-radius: 12px;
+            font-size: 0.95rem;
+            font-weight: 600;
+            transition: all 0.3s ease;
+        }
+
+        .side-menu .nav-link i {
+            width: 20px;
+            text-align: center;
+            color: var(--accent-light);
+        }
+
+        .side-menu .nav-link:hover {
+            background: linear-gradient(135deg, var(--accent-light), var(--accent-color));
+            border-color: transparent;
+            color: #fff;
+            transform: translateX(4px);
+        }
+/* ===== Контент страницы ===== */
+        .toc {
+            background: #fff;
+            border-radius: var(--radius-md);
+            border: 1px solid rgba(52, 152, 219, 0.2);
+            box-shadow: var(--shadow-sm);
+            padding: 18px 22px;
+            margin-bottom: 24px;
+        }
+
+        .toc h2 {
+            font-size: 1.1rem;
+            color: var(--primary-color);
+            display: flex;
+            align-items: center;
+            gap: 8px;
+            margin-bottom: 10px;
+        }
+
+        .toc h2 i {
+            color: var(--accent-color);
+        }
+
+        .toc ul {
+            padding-left: 20px;
+            margin: 0;
+        }
+
+        .toc li {
+            font-size: 0.98rem;
+            margin-bottom: 4px;
+        }
+
+        .toc li a {
+            color: var(--accent-color);
+            text-decoration: none;
+            font-weight: 600;
+            border-bottom: 2px solid rgba(52, 152, 219, 0.35);
+            transition: color 0.2s ease, border-color 0.2s ease;
+        }
+
+        .toc li a:hover {
+            color: var(--xgt-color);
+            border-bottom-color: var(--xgt-color);
+        }
+
+        .section {
+            background: #fff;
+            border-radius: var(--radius-md);
+            border: 1px solid rgba(0, 0, 0, 0.05);
+            padding: 26px 28px;
+            margin-bottom: 22px;
+            box-shadow: var(--shadow-sm);
+            transition: box-shadow 0.3s ease;
+        }
+
+        .section:hover {
+            box-shadow: var(--shadow-md);
+        }
+
+        .section h2 {
+            font-size: 1.4rem;
+            color: var(--primary-color);
+            display: flex;
+            align-items: center;
+            gap: 10px;
+            margin-bottom: 14px;
+        }
+
+        .section h2 i {
+            color: var(--accent-color);
+            font-size: 1.15rem;
+        }
+
+        .section h3 {
+            font-size: 1.1rem;
+            color: var(--secondary-color);
+            margin: 14px 0 8px;
+        }
+
+        .section p,
+        .section li {
+            font-size: 1.02rem;
+            line-height: 1.7;
+        }
+
+        .section ul,
+        .section ol {
+            padding-left: 22px;
+            margin: 8px 0;
+        }
+
+        .case-tag {
+            display: inline-block;
+            margin-right: 8px;
+            margin-bottom: 10px;
+            padding: 3px 14px;
+            border-radius: 999px;
+            font-size: 0.8rem;
+            font-weight: 700;
+            letter-spacing: 0.4px;
+            color: #fff;
+        }
+
+        .case-tag.v21 {
+            background: var(--warning-color);
+        }
+
+        .case-tag.v5 {
+            background: var(--success-color);
+        }
+
+        /* Сравнение схем: старая / новая */
+        .schematic-compare {
+            display: grid;
+            grid-template-columns: 1fr 1fr;
+            gap: 18px;
+            margin: 16px 0 8px;
+        }
+
+        .schematic-card {
+            background: #f3f4f6;
+            border: 1px solid rgba(0, 0, 0, 0.06);
+            border-radius: var(--radius-sm);
+            padding: 14px;
+            box-shadow: var(--shadow-sm);
+            transition: transform 0.25s ease, box-shadow 0.25s ease;
+        }
+
+        .schematic-card:hover {
+            transform: translateY(-3px);
+            box-shadow: var(--shadow-md);
+        }
+
+        .schematic-card .card-head {
+            display: flex;
+            align-items: center;
+            justify-content: space-between;
+            gap: 8px;
+            margin-bottom: 8px;
+            font-weight: 700;
+        }
+
+        .schematic-card .card-head .old {
+            color: var(--xgt-color);
+        }
+
+        .schematic-card .card-head .new {
+            color: var(--success-color);
+        }
+
+        .schematic-card .card-head i {
+            font-size: 0.95rem;
+        }
+
+        .schematic-card figure {
+            margin: 0;
+        }
+
+        .schematic-card figure img {
+            width: 100%;
+            height: auto;
+            display: block;
+            border-radius: var(--radius-sm);
+            border: 1px solid rgba(0, 0, 0, 0.08);
+            cursor: zoom-in;
+            transition: transform 0.3s ease, box-shadow 0.3s ease;
+        }
+
+        .schematic-card figure img:hover {
+            transform: scale(1.02);
+            box-shadow: var(--shadow-md);
+        }
+
+        .schematic-card figcaption {
+            font-size: 0.85rem;
+            color: #7a8699;
+            margin-top: 6px;
+            text-align: center;
+        }
+/* Заметки и предупреждения */
+        .note {
+            background-color: rgba(52, 152, 219, 0.08);
+            border-left: 4px solid var(--accent-color);
+            padding: 14px 18px;
+            margin: 15px 0;
+            border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
+        }
+
+        .warning {
+            background-color: rgba(255, 152, 0, 0.1);
+            border-left: 4px solid #e67e22;
+            padding: 14px 18px;
+            margin: 15px 0;
+            border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
+        }
+
+        .warning.pulse {
+            animation: warning-pulse 2s infinite;
+        }
+
+        @keyframes warning-pulse {
+            0%,
+            100% {
+                box-shadow: 0 0 0 0 rgba(230, 126, 34, 0.35);
+            }
+
+            50% {
+                box-shadow: 0 0 0 10px rgba(230, 126, 34, 0);
+            }
+        }
+
+        .danger {
+            background-color: rgba(231, 76, 60, 0.09);
+            border-left: 4px solid var(--xgt-color);
+            padding: 14px 18px;
+            margin: 15px 0;
+            border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
+        }
+
+        .note i,
+        .warning i,
+        .danger i {
+            margin-right: 8px;
+        }
+
+        .tools-list li {
+            margin-bottom: 6px;
+        }
+
+        .tools-list li i {
+            color: var(--accent-color);
+            width: 22px;
+            text-align: center;
+            margin-right: 6px;
+        }
+
+        /* Кнопки */
+        .btn {
+            display: inline-flex;
+            align-items: center;
+            gap: 8px;
+            padding: 12px 24px;
+            background-color: var(--accent-color);
+            background-image: linear-gradient(135deg, var(--accent-light), var(--accent-color));
+            color: #fff;
+            text-decoration: none;
+            border-radius: 999px;
+            font-weight: 600;
+            font-size: 0.98rem;
+            box-shadow: 0 4px 12px rgba(52, 152, 219, 0.3);
+            transition: all 0.25s ease;
+        }
+
+        .btn:hover {
+            transform: translateY(-2px);
+            box-shadow: 0 8px 18px rgba(52, 152, 219, 0.4);
+            filter: brightness(1.05);
+        }
+
+        .btn i {
+            font-size: 0.9rem;
+        }
+
+        .btn-outline {
+            background: transparent;
+            border: 2px solid var(--accent-color);
+            color: var(--accent-color);
+            box-shadow: none;
+        }
+
+        .btn-outline:hover {
+            background: rgba(52, 152, 219, 0.1);
+            transform: translateY(-2px);
+            box-shadow: 0 6px 14px rgba(52, 152, 219, 0.2);
+        }
+
+.btn-row {
+            display: flex;
+            flex-wrap: wrap;
+            gap: 12px;
+            margin-top: 14px;
+        }
+
+        footer {
+            text-align: center;
+            padding: 26px 20px;
+            margin-top: 28px;
+            border-top: 1px solid rgba(0, 0, 0, 0.08);
+            color: #666;
+            background: rgba(255, 255, 255, 0.6);
+            border-radius: var(--radius-md);
+            box-shadow: var(--shadow-sm);
+        }
+
+        footer a {
+            color: var(--accent-color);
+            font-weight: 600;
+            text-decoration: none;
+        }
+
+        footer a:hover {
+            text-decoration: underline;
+        }
+
+        /* Модальное окно для увеличения изображений */
+        .modal {
+            display: none;
+            position: fixed;
+            z-index: 1000;
+            left: 0;
+            top: 0;
+            width: 100%;
+            height: 100%;
+            background-color: rgba(0, 0, 0, 0.9);
+            backdrop-filter: blur(5px);
+        }
+
+        .modal-content {
+            display: block;
+            margin: auto;
+            max-width: 94%;
+            max-height: 92%;
+            position: absolute;
+            top: 50%;
+            left: 50%;
+            transform: translate(-50%, -50%);
+            border-radius: var(--radius-md);
+            box-shadow: var(--shadow-lg);
+        }
+
+        .close {
+            position: absolute;
+            top: 20px;
+            right: 35px;
+            color: #fff;
+            font-size: 40px;
+            font-weight: bold;
+            cursor: pointer;
+            z-index: 1001;
+            transition: transform 0.3s ease, color 0.3s ease;
+            background: radial-gradient(circle, rgba(255, 255, 255, 0.2), transparent 70%);
+            width: 48px;
+            height: 48px;
+            border-radius: 50%;
+            display: flex;
+            align-items: center;
+            justify-content: center;
+        }
+
+        .close:hover {
+            color: #ff5a5a;
+            transform: rotate(90deg) scale(1.1);
+        }
+
+@media (max-width: 768px) {
+            .container {
+                padding: 15px;
+            }
+
+            header h1 {
+                font-size: 1.5rem;
+            }
+
+            header p {
+                font-size: 0.95rem;
+            }
+
+            .schematic-compare {
+                grid-template-columns: 1fr;
+            }
+
+            .section {
+                padding: 20px;
+            }
+        }
+
+        @media (max-width: 480px) {
+            header h1 {
+                font-size: 1.25rem;
+            }
+
+            .section h2 {
+                font-size: 1.2rem;
+            }
+
+            .btn {
+                font-size: 0.9rem;
+                padding: 10px 20px;
+            }
+        }
+    </style>
+</head>
+
+<body>
+    <div class="container">
+        <!-- Бургер-кнопка -->
+        <button class="hamburger" id="hamburgerBtn" aria-label="Открыть меню" aria-expanded="false">
+            <span></span>
+            <span></span>
+            <span></span>
+        </button>
+
+        <!-- Выдвижное меню -->
+        <div class="side-overlay" id="sideOverlay"></div>
+        <nav class="side-menu" id="sideMenu" aria-label="Основное меню">
+            <div class="side-menu-header">
+                <span><i class="fas fa-plug"></i> Меню</span>
+                <button class="side-menu-close" id="menuClose" aria-label="Закрыть меню">&times;</button>
+            </div>
+            <div class="side-menu-links">
+                <a class="nav-link" href="index.html"><i class="fas fa-home"></i> На главную</a>
+                <a class="nav-link" href="firmware.html"><i class="fas fa-microchip"></i> Прошивка</a>
+                <a class="nav-link" href="firmware/uploader.html"><i class="fas fa-download"></i> Flasher</a>
+                <a class="nav-link" href="mailto:nikelectronics78@gmail.com"><i class="fas fa-headset"></i> Техподдержка</a>
+            </div>
+        </nav>
+
+        <header>
+            <h1><i class="fas fa-project-diagram"></i> Доработка схемы</h1>
+            <p>Информация о доработке электрической схемы диагностического модуля при переходе на новые версии прошивки</p>
+        </header>
+
+        <div class="toc">
+            <h2><i class="fas fa-list-ul"></i> Содержание</h2>
+            <ul>
+                <li><a href="#when">Когда нужна доработка схемы?</a></li>
+                <li><a href="#case1">Случай 1: Переход с прошивки V2.1 &mdash; перепайка R2 для поддержки XGT</a></li>
+                <li><a href="#case2">Случай 2: Переход на прошивку V5.0 &mdash; доработка для пробуждения BMS</a></li>
+                <li><a href="#tools">Рекомендации и безопасность</a></li>
+            </ul>
+        </div>
+
+        <div class="warning pulse">
+            <p><i class="fas fa-exclamation-triangle"></i> <strong>Внимание!</strong> Доработка схемы выполняется
+                пользователем самостоятельно и на свой риск. При отсутствии опыта пайки и работы с электроникой
+                рекомендуется обратиться к специалисту или в <a href="mailto:nikelectronics78@gmail.com">техподдержку</a>.</p>
+        </div>
+
