+        <img class="modal-content" id="modalImage" src="" alt="">
+    </div>
+
+    <script>
+        // Функция для открытия модального окна с изображением
+        function openImageModal(src, alt) {
+            const modal = document.getElementById('imageModal');
+            const modalImg = document.getElementById('modalImage');
+            const closeModal = document.getElementById('closeModal');
+
+            modalImg.src = src;
+            modalImg.alt = alt;
+
+            modal.style.display = 'block';
+
+            closeModal.onclick = function () {
+                modal.style.display = 'none';
+            };
+
+            modal.onclick = function () {
+                modal.style.display = 'none';
+            };
+        }
+
+        // Клик по схеме — открываем в модальном окне
+        document.addEventListener('click', function (event) {
+            const target = event.target;
+            if (target.tagName === 'IMG' && target.closest('.schematic-card')) {
+                openImageModal(target.src, target.alt);
+            }
+        });
+
+        // Закрытие модального окна при нажатии на клавишу Escape
+        document.addEventListener('keydown', function (event) {
+            if (event.key === 'Escape') {
+                const modal = document.getElementById('imageModal');
+                if (modal.style.display === 'block') {
+                    modal.style.display = 'none';
+                }
+            }
+        });
+
+        // ===== Выдвижное меню =====
+        (function () {
+            const burger = document.getElementById('hamburgerBtn');
+            const menu = document.getElementById('sideMenu');
+            const overlay = document.getElementById('sideOverlay');
+            const closeBtn = document.getElementById('menuClose');
+
+            function openMenu() {
+                burger.classList.add('active');
+                menu.classList.add('open');
+                overlay.classList.add('open');
+                burger.setAttribute('aria-expanded', 'true');
+                document.body.style.overflow = 'hidden';
+            }
+
+            function closeMenu() {
+                burger.classList.remove('active');
+                menu.classList.remove('open');
+                overlay.classList.remove('open');
+                burger.setAttribute('aria-expanded', 'false');
+                document.body.style.overflow = '';
+            }
+
+            burger.addEventListener('click', function () {
+                if (menu.classList.contains('open')) {
+                    closeMenu();
+                } else {
+                    openMenu();
+                }
+            });
+
+            closeBtn.addEventListener('click', closeMenu);
+            overlay.addEventListener('click', closeMenu);
+
+            // Закрываем при клике на пункт меню
+            menu.querySelectorAll('.nav-link').forEach(function (link) {
+                link.addEventListener('click', closeMenu);
+            });
+
+            // Закрываем по клавише Escape
+            document.addEventListener('keydown', function (e) {
+                if (e.key === 'Escape') closeMenu();
+            });
+        })();
+    </script>
